//! Independent fixtures are generated by tools/operator_fixtures.py on the benchmark workstation.
use crate::{kernels::device, model::sha};
use cuda_core::{CudaContext, DeviceBuffer, simt::LaunchConfig};
use serde_json::Value;
use std::{fs, path::PathBuf};

fn cfg(items: usize) -> LaunchConfig {
    LaunchConfig {
        grid_dim: (items.div_ceil(128) as u32, 1, 1),
        block_dim: (128, 1, 1),
        shared_mem_bytes: 0,
    }
}
fn rows(n: usize, threads: u32) -> LaunchConfig {
    LaunchConfig {
        grid_dim: (n as u32, 1, 1),
        block_dim: (threads, 1, 1),
        shared_mem_bytes: 0,
    }
}
/// Decode appends sixteen L2-prefetch blocks to attention and O quantization.
fn prefetching(mut config: LaunchConfig) -> LaunchConfig {
    config.grid_dim.0 += 16;
    config
}
/// Prefetch hints target this allocation; outputs must not change.
const HINT: u32 = 1 << 20;

#[test]
fn independent_operators() -> anyhow::Result<()> {
    let root = PathBuf::from(
        std::env::var("CLEAN_OPERATOR_FIXTURES")
            .expect("set CLEAN_OPERATOR_FIXTURES to the independent fixture directory"),
    );
    let manifest: Value = serde_json::from_slice(&fs::read(root.join("manifest.json"))?)?;
    let context = CudaContext::new(0)?;
    let stream = context.default_stream();
    let module = device::load(&context)?;
    // SAFETY: launches below use the declared resource contract and the same
    // immutable fixture allocations validated for the original TMA kernel.
    let pipeline = unsafe { crate::kernels::pipeline_device::load(&context)? };
    let hint = DeviceBuffer::<i8>::zeroed(&stream, HINT as usize)?;
    let hint_cache = DeviceBuffer::<u16>::zeroed(&stream, 4096 * 1024)?;
    for case in manifest["cases"].as_array().unwrap() {
        let op = case["op"].as_str().unwrap();
        let bytes = |key: &str| -> anyhow::Result<Vec<u8>> {
            let meta = &case["tensors"][key];
            let data = fs::read(root.join(meta["file"].as_str().unwrap()))?;
            anyhow::ensure!(
                sha(&data) == meta["sha256"].as_str().unwrap(),
                "fixture hash: {key}"
            );
            Ok(data)
        };
        let f32s = |key: &str| -> anyhow::Result<Vec<f32>> {
            Ok(bytes(key)?
                .chunks_exact(4)
                .map(|b| f32::from_le_bytes(b.try_into().unwrap()))
                .collect())
        };
        let f = |key: &str| -> anyhow::Result<DeviceBuffer<f32>> {
            Ok(DeviceBuffer::from_host(&stream, &f32s(key)?)?)
        };
        let b = |key: &str| -> anyhow::Result<DeviceBuffer<u16>> {
            let values: Vec<_> = bytes(key)?
                .chunks_exact(2)
                .map(|b| u16::from_le_bytes(b.try_into().unwrap()))
                .collect();
            Ok(DeviceBuffer::from_host(&stream, &values)?)
        };
        let i8s = |key: &str| -> anyhow::Result<DeviceBuffer<i8>> {
            let values: Vec<_> = bytes(key)?.into_iter().map(|x| x as i8).collect();
            Ok(DeviceBuffer::from_host(&stream, &values)?)
        };
        let width = case["width"].as_u64().unwrap_or(0) as usize;
        let position = case["position"].as_u64().unwrap_or(0) as u32;
        let position_buffer = DeviceBuffer::from_host(&stream, &[0_u32, position])?;
        if op == "quantize" {
            let x = f("x")?;
            let mut q = DeviceBuffer::<i8>::zeroed(&stream, x.len())?;
            let mut scale = DeviceBuffer::<f32>::zeroed(&stream, x.len() / width)?;
            // SAFETY: generated complete rows, block width matches kernel's shared array.
            unsafe {
                module.quantize(
                    &stream,
                    rows(scale.len(), 1024),
                    &x,
                    width as u32,
                    &mut q,
                    &mut scale,
                    &hint,
                    0,
                    0,
                )?;
            }
            assert_eq!(
                q.to_host_vec(&stream)?
                    .into_iter()
                    .map(|x| x as u8)
                    .collect::<Vec<_>>(),
                bytes("q")?,
                "{}",
                case["name"]
            );
            assert_eq!(
                scale.to_host_vec(&stream)?,
                f32s("scale")?,
                "{}",
                case["name"]
            );
            let mut prefetched_q = DeviceBuffer::<i8>::zeroed(&stream, x.len())?;
            let mut prefetched_scale = DeviceBuffer::<f32>::zeroed(&stream, scale.len())?;
            // SAFETY: as above; appended blocks only issue in-bounds L2 hints.
            unsafe {
                module.quantize(
                    &stream,
                    prefetching(rows(scale.len(), 1024)),
                    &x,
                    width as u32,
                    &mut prefetched_q,
                    &mut prefetched_scale,
                    &hint,
                    0,
                    HINT,
                )?;
            }
            assert_eq!(prefetched_q.to_host_vec(&stream)?, q.to_host_vec(&stream)?);
            assert_eq!(
                prefetched_scale.to_host_vec(&stream)?,
                scale.to_host_vec(&stream)?
            );
            let maximum: Vec<_> = f32s("x")?
                .chunks_exact(width)
                .map(|row| row.iter().fold(1e-8_f32, |m, v| m.max(v.abs())).to_bits())
                .collect();
            let maximum = DeviceBuffer::from_host(&stream, &maximum)?;
            unsafe {
                module.quantize_with_max(
                    &stream,
                    cfg(x.len()),
                    &x,
                    width as u32,
                    &maximum,
                    &mut q,
                    &mut scale,
                )?;
            }
            assert_eq!(
                q.to_host_vec(&stream)?
                    .into_iter()
                    .map(|v| v as u8)
                    .collect::<Vec<_>>(),
                bytes("q")?
            );
            assert_eq!(scale.to_host_vec(&stream)?, f32s("scale")?);
            continue;
        }
        let expected = f32s("out")?;
        let mut out = DeviceBuffer::<f32>::zeroed(&stream, expected.len())?;
        // SAFETY: each independent fixture declares full, validated fixed-model shapes.
        // Buffers remain alive until each branch synchronizes, and outputs do not alias inputs.
        unsafe {
            match op {
                "norm" => {
                    let x = f("x")?;
                    let g = f("gain")?;
                    module.norm(&stream, rows(out.len() / width, 256), &x, &g, &mut out)?;
                    stream.synchronize()?;
                    if width == 4096 {
                        let plain = out.to_host_vec(&stream)?;
                        let mut quant = DeviceBuffer::<i8>::zeroed(&stream, out.len())?;
                        let mut scale = DeviceBuffer::<f32>::zeroed(&stream, out.len() / width)?;
                        module.quantize(
                            &stream,
                            rows(scale.len(), 1024),
                            &out,
                            width as u32,
                            &mut quant,
                            &mut scale,
                            &hint,
                            0,
                            0,
                        )?;
                        let plain_q = quant.to_host_vec(&stream)?;
                        let plain_scale = scale.to_host_vec(&stream)?;
                        let mut maxima = DeviceBuffer::<u32>::zeroed(&stream, scale.len())?;
                        module.norm_quantize(
                            &stream,
                            rows(scale.len(), 1024),
                            &x,
                            &g,
                            &mut out,
                            &mut quant,
                            &mut scale,
                            &mut maxima,
                        )?;
                        assert_eq!(out.to_host_vec(&stream)?, plain, "fused norm output");
                        assert_eq!(quant.to_host_vec(&stream)?, plain_q, "fused norm INT8");
                        assert_eq!(
                            scale.to_host_vec(&stream)?,
                            plain_scale,
                            "fused norm scales"
                        );
                    }
                }
                "linear" => {
                    let q = i8s("q")?;
                    let a = f("asc")?;
                    let w = i8s("w")?;
                    let s = f("ws")?;
                    module.linear(
                        &stream,
                        cfg(out.len() * 32),
                        &q,
                        &a,
                        &w,
                        &s,
                        width as u32,
                        &mut out,
                    )?;
                    stream.synchronize()?;
                    assert_eq!(out.to_host_vec(&stream)?, expected, "DP4A {}", case["name"]);
                    let residual = DeviceBuffer::from_host(
                        &stream,
                        &(0..out.len())
                            .map(|i| ((i % 17) as f32 - 8.0) * 0.0625)
                            .collect::<Vec<_>>(),
                    )?;
                    let mut plain_residual = DeviceBuffer::<f32>::zeroed(&stream, out.len())?;
                    module.residual(
                        &stream,
                        cfg(out.len()),
                        &residual,
                        &out,
                        &mut plain_residual,
                    )?;
                    let mut combined = DeviceBuffer::<f32>::zeroed(&stream, out.len())?;
                    module.linear_residual(
                        &stream,
                        cfg(out.len() * 32),
                        &q,
                        &a,
                        &w,
                        &s,
                        width as u32,
                        &residual,
                        &mut out,
                        &mut combined,
                        width as u32,
                    )?;
                    assert_eq!(out.to_host_vec(&stream)?, expected, "fused projection");
                    assert_eq!(
                        combined
                            .to_host_vec(&stream)?
                            .into_iter()
                            .map(f32::to_bits)
                            .collect::<Vec<_>>(),
                        plain_residual
                            .to_host_vec(&stream)?
                            .into_iter()
                            .map(f32::to_bits)
                            .collect::<Vec<_>>(),
                        "fused residual bits"
                    );
                    let mut second = DeviceBuffer::<f32>::zeroed(&stream, out.len())?;
                    let mut third = DeviceBuffer::<f32>::zeroed(&stream, out.len())?;
                    module.linear_pair(
                        &stream,
                        cfg(out.len() * 2 * 32),
                        &q,
                        &a,
                        width as u32,
                        &w,
                        &s,
                        &mut out,
                        &w,
                        &s,
                        &mut second,
                    )?;
                    assert_eq!(out.to_host_vec(&stream)?, expected, "pair first");
                    assert_eq!(second.to_host_vec(&stream)?, expected, "pair second");
                    module.linear_triple(
                        &stream,
                        cfg(out.len() * 3 * 32),
                        &q,
                        &a,
                        width as u32,
                        &w,
                        &s,
                        &mut out,
                        &w,
                        &s,
                        &mut second,
                        &w,
                        &s,
                        &mut third,
                        &hint_cache,
                        &hint_cache,
                        &position_buffer,
                        width as u32,
                    )?;
                    assert_eq!(out.to_host_vec(&stream)?, expected, "triple first");
                    assert_eq!(second.to_host_vec(&stream)?, expected, "triple second");
                    assert_eq!(third.to_host_vec(&stream)?, expected, "triple third");
                    module.linear_prefill(
                        &stream,
                        cfg(a.len().div_ceil(16) * s.len().div_ceil(8) * 32),
                        &q,
                        &a,
                        &w,
                        &s,
                        width as u32,
                        &mut out,
                    )?;
                    stream.synchronize()?;
                    assert_eq!(out.to_host_vec(&stream)?, expected, "MMA {}", case["name"]);
                    module.linear_splitk(
                        &stream,
                        rows(a.len().div_ceil(16) * s.len().div_ceil(8), 256),
                        &q,
                        &a,
                        &w,
                        &s,
                        width as u32,
                        &mut out,
                    )?;
                    stream.synchronize()?;
                    assert_eq!(
                        out.to_host_vec(&stream)?,
                        expected,
                        "split-K {}",
                        case["name"]
                    );
                    module.linear_tiled(
                        &stream,
                        rows(a.len().div_ceil(32) * s.len().div_ceil(64), 256),
                        &q,
                        &a,
                        &w,
                        &s,
                        width as u32,
                        &mut out,
                    )?;
                    stream.synchronize()?;
                    assert_eq!(
                        out.to_host_vec(&stream)?,
                        expected,
                        "tiled MMA {}",
                        case["name"]
                    );
                    module.linear_tiled_pipeline(
                        &stream,
                        rows(a.len().div_ceil(32) * s.len().div_ceil(64), 256),
                        &q,
                        &a,
                        &w,
                        &s,
                        width as u32,
                        &mut out,
                    )?;
                    assert_eq!(
                        out.to_host_vec(&stream)?,
                        expected,
                        "pipelined tiled {}",
                        case["name"]
                    );
                    module.linear_narrow_pipeline(
                        &stream,
                        rows(a.len().div_ceil(16) * s.len().div_ceil(32), 128),
                        &q,
                        &a,
                        &w,
                        &s,
                        width as u32,
                        &mut out,
                    )?;
                    assert_eq!(
                        out.to_host_vec(&stream)?,
                        expected,
                        "pipelined narrow {}",
                        case["name"]
                    );
                    let amap = crate::tensor::map(&stream, &q, a.len(), width, 64)?;
                    let bmap = crate::tensor::map(&stream, &w, s.len(), width, 128)?;
                    module.linear_large(
                        &stream,
                        rows(a.len().div_ceil(64) * s.len().div_ceil(128), 256),
                        &amap,
                        &a,
                        &bmap,
                        &s,
                        width as u32,
                        &mut out,
                    )?;
                    assert_eq!(
                        out.to_host_vec(&stream)?,
                        expected,
                        "original TMA {}",
                        case["name"]
                    );
                    let launch =
                        pipeline.prepare_linear_large_pipeline(cuda_core::LaunchConfig1D::new(
                            (a.len().div_ceil(64) * s.len().div_ceil(128)) as u32,
                            256,
                            50176,
                        ))?;
                    pipeline.linear_large_pipeline(
                        &stream,
                        &launch,
                        &amap,
                        &a,
                        &bmap,
                        &s,
                        width as u32,
                        &mut out,
                    )?;
                    stream.synchronize()?;
                }
                "rope" => {
                    let x = f("x")?;
                    let t = f("table")?;
                    module.rope(
                        &stream,
                        cfg(out.len() / 2),
                        &x,
                        &t,
                        32,
                        &position_buffer,
                        &mut out,
                    )?;
                    stream.synchronize()?;
                    let gain = DeviceBuffer::from_host(
                        &stream,
                        &(0..128)
                            .map(|i| (i as f32 % 13.0 - 6.0) * 0.25)
                            .collect::<Vec<_>>(),
                    )?;
                    let mut normed = DeviceBuffer::<f32>::zeroed(&stream, x.len())?;
                    let mut plain = DeviceBuffer::<f32>::zeroed(&stream, x.len())?;
                    module.norm(&stream, rows(x.len() / 128, 256), &x, &gain, &mut normed)?;
                    module.rope(
                        &stream,
                        cfg(x.len() / 2),
                        &normed,
                        &t,
                        32,
                        &position_buffer,
                        &mut plain,
                    )?;
                    let mut fused = DeviceBuffer::from_host(&stream, &f32s("x")?)?;
                    module.norm_rope(
                        &stream,
                        rows(x.len() / 128, 128),
                        &mut fused,
                        &gain,
                        &t,
                        32,
                        &position_buffer,
                    )?;
                    assert_eq!(
                        fused.to_host_vec(&stream)?,
                        plain.to_host_vec(&stream)?,
                        "fused head norm/RoPE"
                    );
                    let nr = x.len() / 4096;
                    let raw_k = f32s("x")?[..nr * 1024].to_vec();
                    let k = DeviceBuffer::from_host(&stream, &raw_k)?;
                    let v = DeviceBuffer::from_host(&stream, &raw_k)?;
                    let mut normalized_k = DeviceBuffer::<f32>::zeroed(&stream, k.len())?;
                    let mut rotated_k = DeviceBuffer::<f32>::zeroed(&stream, k.len())?;
                    module.norm(
                        &stream,
                        rows(k.len() / 128, 256),
                        &k,
                        &gain,
                        &mut normalized_k,
                    )?;
                    module.rope(
                        &stream,
                        cfg(k.len() / 2),
                        &normalized_k,
                        &t,
                        8,
                        &position_buffer,
                        &mut rotated_k,
                    )?;
                    let mut reference_ck = DeviceBuffer::<u16>::zeroed(&stream, 4096 * 1024)?;
                    let mut reference_cv = DeviceBuffer::<u16>::zeroed(&stream, 4096 * 1024)?;
                    module.cache(
                        &stream,
                        cfg(k.len()),
                        &rotated_k,
                        &v,
                        &position_buffer,
                        &mut reference_ck,
                        &mut reference_cv,
                    )?;
                    let mut fused_q = DeviceBuffer::from_host(&stream, &f32s("x")?)?;
                    let mut fused_k = DeviceBuffer::from_host(&stream, &raw_k)?;
                    let mut ck = DeviceBuffer::<u16>::zeroed(&stream, 4096 * 1024)?;
                    let mut cv = DeviceBuffer::<u16>::zeroed(&stream, 4096 * 1024)?;
                    module.prepare_qk(
                        &stream,
                        rows(nr * 40, 128),
                        &mut fused_q,
                        &mut fused_k,
                        &v,
                        &gain,
                        &gain,
                        &t,
                        &position_buffer,
                        &mut ck,
                        &mut cv,
                    )?;
                    assert_eq!(
                        fused_q.to_host_vec(&stream)?,
                        plain.to_host_vec(&stream)?,
                        "prepared Q"
                    );
                    assert_eq!(
                        fused_k.to_host_vec(&stream)?,
                        rotated_k.to_host_vec(&stream)?,
                        "prepared K"
                    );
                    assert_eq!(
                        ck.to_host_vec(&stream)?,
                        reference_ck.to_host_vec(&stream)?,
                        "prepared K cache"
                    );
                    assert_eq!(
                        cv.to_host_vec(&stream)?,
                        reference_cv.to_host_vec(&stream)?,
                        "prepared V cache"
                    );
                }
                "attention" => {
                    let q = f("q")?;
                    // Fixtures describe logical [token, head, coordinate] keys.
                    // Pack those same values into the runtime's coordinate-major cache.
                    let raw_k: Vec<_> = bytes("k")?
                        .chunks_exact(2)
                        .map(|b| u16::from_le_bytes(b.try_into().unwrap()))
                        .collect();
                    let mut transposed = vec![0_u16; 4096 * 1024];
                    for (i, value) in raw_k.iter().enumerate() {
                        transposed[i % 1024 * 4096 + i / 1024] = *value;
                    }
                    let k = DeviceBuffer::from_host(&stream, &transposed)?;
                    let mut values = vec![0_u16; 4096 * 1024];
                    for (i, bytes) in bytes("v")?.chunks_exact(2).enumerate() {
                        values[i] = u16::from_le_bytes(bytes.try_into().unwrap());
                    }
                    let v = DeviceBuffer::from_host(&stream, &values)?;
                    module.attention(
                        &stream,
                        rows(out.len() / 128, 128),
                        &q,
                        &k,
                        &v,
                        &position_buffer,
                        &mut out,
                        &hint,
                        0,
                        0,
                    )?;
                    stream.synchronize()?;
                    let unsplit = out.to_host_vec(&stream)?;
                    let mut prefetched = DeviceBuffer::<f32>::zeroed(&stream, out.len())?;
                    module.attention(
                        &stream,
                        prefetching(rows(out.len() / 128, 128)),
                        &q,
                        &k,
                        &v,
                        &position_buffer,
                        &mut prefetched,
                        &hint,
                        0,
                        HINT,
                    )?;
                    assert_eq!(
                        prefetched.to_host_vec(&stream)?,
                        unsplit,
                        "prefetching attention"
                    );
                    if position as usize + out.len() / 4096 <= 512 {
                        module.attention_prefill(
                            &stream,
                            rows(out.len() / 512, 512),
                            &q,
                            &k,
                            &v,
                            &position_buffer,
                            &mut out,
                        )?;
                        stream.synchronize()?;
                        assert_eq!(
                            out.to_host_vec(&stream)?,
                            unsplit,
                            "four-head prefill attention"
                        );
                    }

                    let mut scores = DeviceBuffer::<f32>::zeroed(&stream, out.len() / 128 * 4096)?;
                    let tiles = (position as usize + out.len() / 4096).div_ceil(64);
                    module.attention_scores(
                        &stream,
                        rows(out.len() / 128 * tiles, 128),
                        &q,
                        &k,
                        &position_buffer,
                        tiles as u32,
                        &mut scores,
                    )?;
                    module.attention_finish(
                        &stream,
                        rows(out.len() / 128, 128),
                        &scores,
                        &v,
                        &position_buffer,
                        &mut out,
                    )?;
                    stream.synchronize()?;
                    assert_eq!(out.to_host_vec(&stream)?, unsplit, "split attention");
                    // Exercise the decode launch shape, including prefetch blocks.
                    module.attention_softmax(
                        &stream,
                        prefetching(rows(out.len() / 128, 128)),
                        &mut scores,
                        &position_buffer,
                        &hint,
                        0,
                        HINT,
                    )?;
                    module.attention_values(
                        &stream,
                        rows(out.len() / 32, 32),
                        &scores,
                        &v,
                        &position_buffer,
                        &mut out,
                    )?;
                    stream.synchronize()?;
                    assert_eq!(out.to_host_vec(&stream)?, unsplit, "split PV attention");
                }
                "swiglu" => {
                    let g = f("gate")?;
                    let u = f("up")?;
                    let mut maxima = DeviceBuffer::from_host(&stream, &[1e-8_f32.to_bits()])?;
                    module.swiglu(&stream, cfg(out.len()), &g, &u, &mut out, &mut maxima)?;
                    stream.synchronize()?;
                    let maximum = out
                        .to_host_vec(&stream)?
                        .iter()
                        .fold(1e-8_f32, |m, v| m.max(v.abs()));
                    assert_eq!(
                        maxima.to_host_vec(&stream)?[0],
                        maximum.to_bits(),
                        "SwiGLU maximum"
                    );
                }
                "residual" => {
                    let a = f("a")?;
                    let b = f("b")?;
                    module.residual(&stream, cfg(out.len()), &a, &b, &mut out)?;
                    stream.synchronize()?;
                }
                "head" => {
                    let x = f("x")?;
                    let w = b("w")?;
                    module.head(&stream, cfg(out.len() * 32), &x, &w, &mut out)?;
                    stream.synchronize()?;
                    let original: Vec<_> = out
                        .to_host_vec(&stream)?
                        .into_iter()
                        .map(f32::to_bits)
                        .collect();
                    let packed = crate::packing::PackedBf16::new(&w.to_host_vec(&stream)?);
                    let words = DeviceBuffer::from_host(&stream, &packed.words)?;
                    let offsets = DeviceBuffer::from_host(&stream, &packed.offsets)?;
                    let exceptions = DeviceBuffer::from_host(&stream, &packed.exceptions)?;
                    module.head_packed(
                        &stream,
                        cfg(out.len() * 32),
                        &x,
                        &words,
                        &offsets,
                        &exceptions,
                        &mut out,
                        6144,
                    )?;
                    assert_eq!(
                        out.to_host_vec(&stream)?
                            .into_iter()
                            .map(f32::to_bits)
                            .collect::<Vec<_>>(),
                        original,
                        "packed head exact bits"
                    );
                }
                "embedding" => {
                    let ids: Vec<_> = bytes("ids")?
                        .chunks_exact(4)
                        .map(|b| u32::from_le_bytes(b.try_into().unwrap()))
                        .collect();
                    let ids = DeviceBuffer::from_host(&stream, &ids)?;
                    let w = b("w")?;
                    module.embedding(&stream, cfg(out.len()), &ids, &w, &mut out)?;
                    stream.synchronize()?;
                }
                _ => anyhow::bail!("unknown operator {op}"),
            }
        }
        let got = out.to_host_vec(&stream)?;
        let exact = matches!(op, "linear" | "embedding" | "residual" | "rope");
        let mut error = 0_f64;
        let mut energy = 0_f64;
        for (i, (&a, &b)) in got.iter().zip(&expected).enumerate() {
            assert!(
                a.is_finite() && (a - b).abs() <= if exact { 0.0 } else { 2e-4 + 0.01 * b.abs() },
                "{} element {i}: {a} vs {b}",
                case["name"]
            );
            error += (a as f64 - b as f64).powi(2);
            energy += (b as f64).powi(2);
        }
        assert!(
            (error / energy.max(1e-20)).sqrt() <= 0.005,
            "{} relative L2",
            case["name"]
        );
    }
    Ok(())
}

#[test]
fn gpu_argmax_ties_and_rejection() -> anyhow::Result<()> {
    let ctx = CudaContext::new(0)?;
    let stream = ctx.default_stream();
    let module = device::load(&ctx)?;
    let mut cases = vec![
        vec![0.0, -0.0],
        vec![-0.0, 0.0],
        vec![f32::MIN],
        vec![f32::NAN],
        vec![0.0, f32::INFINITY],
        vec![f32::NEG_INFINITY, 0.0],
    ];
    for n in [31, 32, 33, 1023, 1024, 1025, crate::VOCAB] {
        let mut x: Vec<_> = (0..n).map(|i| (i % 97) as f32).collect();
        x[n - 1] = f32::MAX;
        cases.push(x.clone());
        x[7] = f32::MAX;
        cases.push(x);
    }
    for x in cases {
        let input = DeviceBuffer::from_host(&stream, &x)?;
        let mut output = DeviceBuffer::<u32>::zeroed(&stream, 1)?;
        // SAFETY: exact 1024-thread CTA and one result slot; all inputs admitted by this reduction.
        unsafe {
            module.select_token(&stream, rows(1, 1024), &input, &mut output)?;
        }
        let actual = output.to_host_vec(&stream)?[0];
        assert_eq!(actual, crate::model::argmax(&x).unwrap_or(u32::MAX));
    }
    Ok(())
}

#[test]
fn packed_bf16_exhaustive_gpu() -> anyhow::Result<()> {
    let input: Vec<u16> = (0..131072)
        .map(|i| (i as u16).wrapping_mul(40503))
        .collect();
    let packed = crate::packing::PackedBf16::new(&input);
    let context = CudaContext::new(0)?;
    let stream = context.default_stream();
    let module = device::load(&context)?;
    let words = DeviceBuffer::from_host(&stream, &packed.words)?;
    let offsets = DeviceBuffer::from_host(&stream, &packed.offsets)?;
    let exceptions = DeviceBuffer::from_host(&stream, &packed.exceptions)?;
    let mut out = DeviceBuffer::<u16>::zeroed(&stream, input.len())?;
    // SAFETY: the private packer produces the complete matching bitstream; every
    // exceptional code points within its own chunk's at-most-256-entry table.
    unsafe {
        module.unpack_head(
            &stream,
            cfg(out.len()),
            &words,
            &offsets,
            &exceptions,
            &mut out,
        )?;
    }
    assert_eq!(out.to_host_vec(&stream)?, input);
    Ok(())
}

#[test]
fn fused_gate_up_matches_separate() -> anyhow::Result<()> {
    let ctx = CudaContext::new(0)?;
    let stream = ctx.default_stream();
    let module = device::load(&ctx)?;
    for (k, n) in [(128_usize, 33_usize), (4096, 12288)] {
        let q = DeviceBuffer::from_host(
            &stream,
            &(0..k)
                .map(|i| ((i * 13 % 255) as i32 - 127) as i8)
                .collect::<Vec<_>>(),
        )?;
        let w0 = DeviceBuffer::from_host(
            &stream,
            &(0..k * n)
                .map(|i| ((i * 31 % 255) as i32 - 127) as i8)
                .collect::<Vec<_>>(),
        )?;
        let w1 = DeviceBuffer::from_host(
            &stream,
            &(0..k * n)
                .map(|i| ((i * 17 % 251) as i32 - 125) as i8)
                .collect::<Vec<_>>(),
        )?;
        let asc = DeviceBuffer::from_host(&stream, &[0.002_f32])?;
        let s0 = DeviceBuffer::from_host(
            &stream,
            &(0..n)
                .map(|i| 0.0001 * ((i % 7 + 1) as f32))
                .collect::<Vec<_>>(),
        )?;
        let s1 = DeviceBuffer::from_host(
            &stream,
            &(0..n)
                .map(|i| 0.0001 * ((i % 11 + 1) as f32))
                .collect::<Vec<_>>(),
        )?;
        let mut g = DeviceBuffer::<f32>::zeroed(&stream, n)?;
        let mut u = DeviceBuffer::<f32>::zeroed(&stream, n)?;
        let mut act = DeviceBuffer::<f32>::zeroed(&stream, n)?;
        let mut maximum = DeviceBuffer::from_host(&stream, &[1e-8_f32.to_bits()])?;
        // SAFETY: complete aligned rows; separate read-only matrices and outputs.
        unsafe {
            module.linear_pair(
                &stream,
                cfg(n * 64),
                &q,
                &asc,
                k as u32,
                &w0,
                &s0,
                &mut g,
                &w1,
                &s1,
                &mut u,
            )?;
            module.swiglu(&stream, cfg(n), &g, &u, &mut act, &mut maximum)?;
        }
        let bits = |x: Vec<f32>| x.into_iter().map(f32::to_bits).collect::<Vec<_>>();
        let expected_g = bits(g.to_host_vec(&stream)?);
        let expected_u = bits(u.to_host_vec(&stream)?);
        let values = act.to_host_vec(&stream)?;
        let expected_max = values.iter().fold(1e-8_f32, |m, v| m.max(v.abs()));
        let expected_act = bits(values);
        maximum.copy_from_host(&stream, &[1e-8_f32.to_bits()])?;
        // SAFETY: exactly eight full warps per CTA, one admitted activation row.
        unsafe {
            module.linear_swiglu(
                &stream,
                rows(n.div_ceil(8), 256),
                &q,
                &asc,
                k as u32,
                &w0,
                &s0,
                &mut g,
                &w1,
                &s1,
                &mut u,
                &mut act,
                &mut maximum,
                4096,
            )?;
        }
        assert_eq!(bits(g.to_host_vec(&stream)?), expected_g, "gate bits");
        assert_eq!(bits(u.to_host_vec(&stream)?), expected_u, "up bits");
        assert_eq!(
            bits(act.to_host_vec(&stream)?),
            expected_act,
            "activation bits"
        );
        assert_eq!(
            maximum.to_host_vec(&stream)?[0],
            expected_max.to_bits(),
            "activation maximum"
        );
    }
    Ok(())
}

#[test]
fn integer_rounding_boundaries() -> anyhow::Result<()> {
    let mut input: Vec<_> = (0..=u16::MAX)
        .map(|x| f32::from_bits(u32::from(x) << 16))
        .collect();
    input.extend((-131072..=131072).map(|x| x as f32 / 1024.0));
    for i in -127..127 {
        let tie = i as f32 + 0.5;
        for bits in [tie.to_bits() - 1, tie.to_bits(), tie.to_bits() + 1] {
            input.push(f32::from_bits(bits));
        }
    }
    input.extend((0..1_000_000_u32).map(|x| f32::from_bits(x.wrapping_mul(2654435761))));
    let expected: Vec<_> = input
        .iter()
        .map(|&x| f64::from(x).clamp(-127.0, 127.0).round_ties_even() as i8)
        .collect();
    let ctx = CudaContext::new(0)?;
    let stream = ctx.default_stream();
    let module = device::load(&ctx)?;
    let device_input = DeviceBuffer::from_host(&stream, &input)?;
    let mut out = DeviceBuffer::<i8>::zeroed(&stream, input.len())?;
    unsafe {
        module.rounding_probe(&stream, cfg(input.len()), &device_input, &mut out)?;
    }
    let actual = out.to_host_vec(&stream)?;
    for (i, (&a, &e)) in actual.iter().zip(&expected).enumerate() {
        assert_eq!(a, e, "input bits {:08x}", input[i].to_bits());
    }
    Ok(())
}

#[test]
fn paged_attention_matches_contiguous_ragged_queries() -> anyhow::Result<()> {
    let context = CudaContext::new(0)?;
    let stream = context.default_stream();
    let module = device::load(&context)?;
    let stride = 4096;
    let pages_per_sequence = stride / 64;
    let table: Vec<u32> = (0..128).map(|i| (i * 37 % 128) as u32).collect();
    let mut paged_k = vec![0_u16; 2 * stride * 1024];
    let mut paged_v = paged_k.clone();
    let mut contiguous = Vec::new();
    for slot in 0..2 {
        let mut k = vec![0_u16; stride * 1024];
        let mut v = k.clone();
        for position in 0..stride {
            let page = table[slot * pages_per_sequence + position / 64] as usize;
            for coordinate in 0..1024 {
                let key =
                    (((position * 17 + coordinate * 3 + slot * 31) % 37) as f32 - 18.0) / 32.0;
                let value =
                    (((position * 23 + coordinate * 7 + slot * 11) % 51) as f32 - 25.0) / 32.0;
                let kb = (key.to_bits() >> 16) as u16;
                let vb = (value.to_bits() >> 16) as u16;
                k[coordinate * stride + position] = kb;
                v[position * 1024 + coordinate] = vb;
                paged_k[page * 65536 + coordinate * 64 + position % 64] = kb;
                paged_v[(page * 64 + position % 64) * 1024 + coordinate] = vb;
            }
        }
        contiguous.push((
            DeviceBuffer::from_host(&stream, &k)?,
            DeviceBuffer::from_host(&stream, &v)?,
        ));
    }
    // Partial query groups, page crossings, shuffled slots and a native 4K tail.
    let queries: [(usize, usize); 17] = [
        (1, 4095),
        (0, 0),
        (0, 1),
        (0, 2),
        (0, 3),
        (1, 62),
        (1, 63),
        (1, 64),
        (0, 128),
        (0, 129),
        (1, 511),
        (1, 512),
        (1, 513),
        (1, 514),
        (1, 515),
        (1, 516),
        (0, 63),
    ];
    let info: Vec<u32> = queries
        .iter()
        .flat_map(|&(slot, pos)| [slot as u32, pos as u32])
        .collect();
    let q: Vec<f32> = (0..queries.len() * 4096)
        .map(|i| ((i * 7 % 31) as f32 - 15.0) / 16.0)
        .collect();
    let q_device = DeviceBuffer::from_host(&stream, &q)?;
    let info = DeviceBuffer::from_host(&stream, &info)?;
    let page_table = DeviceBuffer::from_host(&stream, &table)?;
    let k_device = DeviceBuffer::from_host(&stream, &paged_k)?;
    let v_device = DeviceBuffer::from_host(&stream, &paged_v)?;
    let mut scores = DeviceBuffer::<f32>::zeroed(&stream, queries.len() * 32 * stride)?;
    let mut output = DeviceBuffer::<f32>::zeroed(&stream, queries.len() * 4096)?;
    // SAFETY: the table is a permutation of the 128 allocated physical pages;
    // every row selects one valid sequence/position and owns disjoint scratch.
    unsafe {
        module.attention_scores_paged(
            &stream,
            rows(queries.len() * 32 * 64, 128),
            &q_device,
            &k_device,
            &info,
            &page_table,
            64,
            stride as u32,
            64,
            &mut scores,
        )?;
        module.attention_softmax_paged(
            &stream,
            rows(queries.len() * 32, 128),
            &mut scores,
            &info,
            stride as u32,
        )?;
        module.attention_values_paged(
            &stream,
            rows(queries.len() * 32 * 4, 32),
            &scores,
            &v_device,
            &info,
            &page_table,
            64,
            stride as u32,
            &mut output,
        )?;
    }
    let actual = output.to_host_vec(&stream)?;
    let probabilities = scores.to_host_vec(&stream)?;
    // The grouped path shares K/V staging across all four GQA heads. Compare
    // its complete probability/output tensors before checking the independent
    // contiguous implementation below, including shuffled pages and tails.
    unsafe {
        module.attention_scores_grouped(
            &stream,
            rows(queries.len() * 8 * 64, 128),
            &q_device,
            &k_device,
            &info,
            &page_table,
            64,
            stride as u32,
            64,
            &mut scores,
        )?;
        module.attention_softmax_paged(
            &stream,
            rows(queries.len() * 32, 128),
            &mut scores,
            &info,
            stride as u32,
        )?;
        module.attention_values_grouped(
            &stream,
            rows(queries.len() * 8 * 4, 32),
            &scores,
            &v_device,
            &info,
            &page_table,
            64,
            stride as u32,
            &mut output,
        )?;
    }
    assert_eq!(scores.to_host_vec(&stream)?, probabilities);
    assert_eq!(output.to_host_vec(&stream)?, actual);
    let query_tiles =
        DeviceBuffer::from_host(&stream, &[0_u32, 1, 1, 4, 5, 3, 8, 2, 10, 4, 14, 2, 16, 1])?;
    // SAFETY: these seven groups partition every query, each contains one to
    // four consecutive positions from one slot, and the page table is unchanged.
    unsafe {
        module.attention_scores_tiled(
            &stream,
            rows(7 * 8 * 64, 256),
            &q_device,
            &k_device,
            &info,
            &page_table,
            64,
            stride as u32,
            64,
            &query_tiles,
            &mut scores,
        )?;
        module.attention_softmax_paged(
            &stream,
            rows(queries.len() * 32, 128),
            &mut scores,
            &info,
            stride as u32,
        )?;
        module.attention_values_tiled(
            &stream,
            rows(7 * 8 * 4, 128),
            &scores,
            &v_device,
            &info,
            &page_table,
            64,
            stride as u32,
            &query_tiles,
            &mut output,
        )?;
    }
    assert_eq!(scores.to_host_vec(&stream)?, probabilities);
    assert_eq!(output.to_host_vec(&stream)?, actual);
    let hint = DeviceBuffer::<i8>::zeroed(&stream, 1)?;
    for (row, &(slot, position)) in queries.iter().enumerate() {
        let q = DeviceBuffer::from_host(&stream, &q[row * 4096..(row + 1) * 4096])?;
        let control = DeviceBuffer::from_host(&stream, &[0, position as u32])?;
        let mut scores = DeviceBuffer::<f32>::zeroed(&stream, 32 * stride)?;
        let mut expected = DeviceBuffer::<f32>::zeroed(&stream, 4096)?;
        let tiles = (position + 1).div_ceil(64);
        // SAFETY: one valid legacy query against its fully initialized cache.
        unsafe {
            module.attention_scores(
                &stream,
                rows(32 * tiles, 128),
                &q,
                &contiguous[slot].0,
                &control,
                tiles as u32,
                &mut scores,
            )?;
            module.attention_softmax(&stream, rows(32, 128), &mut scores, &control, &hint, 0, 0)?;
            module.attention_values(
                &stream,
                rows(32 * 4, 32),
                &scores,
                &contiguous[slot].1,
                &control,
                &mut expected,
            )?;
        }
        let expected = expected.to_host_vec(&stream)?;
        for (column, (&a, &e)) in actual[row * 4096..(row + 1) * 4096]
            .iter()
            .zip(&expected)
            .enumerate()
        {
            assert_eq!(a.to_bits(), e.to_bits(), "row {row}, coordinate {column}");
        }
    }
    Ok(())
}

#[test]
fn paged_attention_reaches_native_context() -> anyhow::Result<()> {
    let context = CudaContext::new(0)?;
    let stream = context.default_stream();
    let module = device::load(&context)?;
    let stride = 32768;
    let pages: Vec<u32> = (0..512).rev().collect();
    // Uniform logits give exactly 1/32768. Constant V across keys has an
    // independently known mean, with distinct values for every KV coordinate.
    let values: Vec<u16> = (0..stride * 1024)
        .map(|i| {
            let v = ((i % 1024 % 97) as f32 - 48.0) / 16.0;
            (v.to_bits() >> 16) as u16
        })
        .collect();
    let k = DeviceBuffer::<u16>::zeroed(&stream, values.len())?;
    let v = DeviceBuffer::from_host(&stream, &values)?;
    let q = DeviceBuffer::<f32>::zeroed(&stream, 4096)?;
    let info = DeviceBuffer::from_host(&stream, &[0, (stride - 1) as u32])?;
    let table = DeviceBuffer::from_host(&stream, &pages)?;
    let mut scores = DeviceBuffer::<f32>::zeroed(&stream, 32 * stride)?;
    let mut output = DeviceBuffer::<f32>::zeroed(&stream, 4096)?;
    // SAFETY: the single sequence maps all 512 pages exactly once, and its
    // visible prefix is fully initialized through the final native position.
    unsafe {
        module.attention_scores_paged(
            &stream,
            rows(32 * 512, 128),
            &q,
            &k,
            &info,
            &table,
            512,
            stride as u32,
            512,
            &mut scores,
        )?;
        module.attention_softmax_paged(
            &stream,
            rows(32, 128),
            &mut scores,
            &info,
            stride as u32,
        )?;
        module.attention_values_paged(
            &stream,
            rows(32 * 4, 32),
            &scores,
            &v,
            &info,
            &table,
            512,
            stride as u32,
            &mut output,
        )?;
    }
    let actual = output.to_host_vec(&stream)?;
    unsafe {
        module.attention_scores_grouped(
            &stream,
            rows(8 * 512, 128),
            &q,
            &k,
            &info,
            &table,
            512,
            stride as u32,
            512,
            &mut scores,
        )?;
        module.attention_softmax_paged(
            &stream,
            rows(32, 128),
            &mut scores,
            &info,
            stride as u32,
        )?;
        module.attention_values_grouped(
            &stream,
            rows(8 * 4, 32),
            &scores,
            &v,
            &info,
            &table,
            512,
            stride as u32,
            &mut output,
        )?;
    }
    assert_eq!(output.to_host_vec(&stream)?, actual);
    for (i, value) in actual.into_iter().enumerate() {
        let kv_coordinate = (i / 128 / 4) * 128 + i % 128;
        let expected = ((kv_coordinate % 97) as f32 - 48.0) / 16.0;
        assert_eq!(value.to_bits(), expected.to_bits(), "coordinate {i}");
    }
    Ok(())
}

#[test]
fn head32_independent_reference() -> anyhow::Result<()> {
    let context = CudaContext::new(0)?;
    let stream = context.new_stream()?;
    let module = device::load(&context)?;
    // Sixteen vocabulary columns exercise two CTAs per output group, while
    // the real vocabulary stride and all untouched columns remain guarded.
    let weights: Vec<u16> = (0..16 * 4096)
        .map(|i| {
            (((i * 17 % 2) << 15) | (((i * 37 % 23) + 105) << 7) | ((i * 61 + 7) % 128)) as u16
        })
        .collect();
    let packed = crate::packing::PackedBf16::new(&weights);
    assert!(packed.exceptions.len() > 1);
    let words = DeviceBuffer::from_host(&stream, &packed.words)?;
    let offsets = DeviceBuffer::from_host(&stream, &packed.offsets)?;
    let exceptions = DeviceBuffer::from_host(&stream, &packed.exceptions)?;
    for nr in [1_usize, 3, 8, 16, 17, 31, 32, 33, 63, 64, 65] {
        let values: Vec<f32> = (0..(nr + 3) * 4096)
            .map(|i| {
                let x = ((i * 37 + i / 4096 * 19 + 11) % 511) as f32 / 128.0 - 2.0;
                let bits = x.to_bits();
                f32::from_bits(bits.wrapping_add(0x7fff + ((bits >> 16) & 1)) & 0xffff0000)
            })
            .collect();
        let selected: Vec<u32> = (0..nr).map(|i| ((nr + 2 - i) % (nr + 3)) as u32).collect();
        let sentinel = -12345.25_f32;
        let mut expected = vec![sentinel.to_bits(); nr * 151936 + 64];
        for (r, &selected_row) in selected.iter().enumerate() {
            for column in 0..16 {
                let mut lanes = [0.0_f32; 32];
                for lane in 0..32 {
                    for k in (lane..4096).step_by(32) {
                        let weight = f32::from_bits(u32::from(weights[column * 4096 + k]) << 16);
                        let product = values[selected_row as usize * 4096 + k] * weight;
                        lanes[lane] += product;
                    }
                }
                for distance in [16, 8, 4, 2, 1] {
                    let prior = lanes;
                    for lane in 0..32 - distance {
                        lanes[lane] = prior[lane] + prior[lane + distance];
                    }
                }
                assert!(lanes[0].is_finite());
                let bits = lanes[0].to_bits();
                expected[r * 151936 + column] =
                    bits.wrapping_add(0x7fff + ((bits >> 16) & 1)) & 0xffff0000;
            }
        }
        let x = DeviceBuffer::from_host(&stream, &values)?;
        let selected = DeviceBuffer::from_host(&stream, &selected)?;
        let mut output = DeviceBuffer::from_host(&stream, &vec![sentinel; expected.len()])?;
        for graph in [false, true] {
            output.copy_from_host(&stream, &vec![sentinel; expected.len()])?;
            // SAFETY: two vocabulary CTAs, positive output count, complete 4096-wide
            // inputs and losslessly packed weights. Padded selected rows never publish.
            let mut launch = || -> anyhow::Result<()> {
                unsafe {
                    module.head_packed_thirtytwo_staged(
                        &stream,
                        rows(2 * nr.div_ceil(32), 256),
                        &x,
                        &selected,
                        &words,
                        &offsets,
                        &exceptions,
                        &mut output,
                    )?;
                }
                Ok(())
            };
            if graph {
                let capture = unsafe { crate::graph::Graph::capture(&stream, false, launch)? };
                unsafe {
                    capture.launch()?;
                }
                stream.synchronize()?;
            } else {
                launch()?;
            }
            let actual: Vec<u32> = output
                .to_host_vec(&stream)?
                .into_iter()
                .map(f32::to_bits)
                .collect();
            assert_eq!(actual, expected, "head32 rows={nr}, graph={graph}");
            println!(
                "HEAD32_REFERENCE {}",
                serde_json::json!({"rows":nr,"graph":graph,"vocabulary_columns":16})
            );
        }
    }
    Ok(())
}

fn certificate_host_rows(values: &[f32], nr: usize) -> (Vec<i8>, Vec<f64>) {
    let mut digits = vec![0_i8; 3 * nr * 4096];
    let mut stats = vec![0.0_f64; nr * 5];
    for row in 0..nr {
        let values = &values[row * 4096..(row + 1) * 4096];
        let valid = values.iter().all(|v| {
            v.to_bits() & 65535 == 0
                && v.is_finite()
                && (*v == 0.0 || (v.abs() >= 2.0_f32.powi(-50) && v.abs() <= 2.0_f32.powi(30)))
        });
        let maximum = values.iter().map(|v| v.abs()).fold(0.0_f32, f32::max);
        let mut scale = 1.0_f32;
        if valid && maximum > 0.0 {
            scale = f32::from_bits(((maximum.to_bits() >> 23) - 22) << 23);
            if maximum > 8355711.0 * scale {
                scale *= 2.0;
            }
        }
        let mut sums = [0.0_f64; 4];
        for (j, &value) in values.iter().enumerate() {
            let value = if valid { value } else { 0.0 };
            let q = (value / scale).round_ties_even() as i32;
            assert!(q.abs() <= 8355711);
            // Euclidean division independently defines balanced base-256 digits.
            let middle_high = (q + 128).div_euclid(256);
            let high = (middle_high + 128).div_euclid(256);
            let parts = [q - middle_high * 256, middle_high - high * 256, high];
            assert!(parts.iter().all(|v| (-128..=127).contains(v)));
            assert_eq!(parts[0] + 256 * parts[1] + 65536 * parts[2], q);
            for plane in 0..3 {
                digits[plane * nr * 4096 + row * 4096 + j] = parts[plane] as i8;
            }
            let v = value as f64;
            let a = (q as f64) * (scale as f64);
            let e = v - a;
            sums[0] += v * v;
            sums[1] += a * a;
            sums[2] += e * e;
            sums[3] += v * v * (133 - j / 32) as f64;
        }
        stats[row * 5] = scale as f64;
        // Each square/product is exact in f64 in this guarded BF16 domain.
        // 2^-39 exceeds the 4096-term positive-sum relative error bound.
        for i in 0..4 {
            stats[row * 5 + 1 + i] = (sums[i] * (1.0 + 2.0_f64.powi(-39)))
                .next_up()
                .sqrt()
                .next_up();
        }
        if !valid {
            stats[row * 5 + 4] = f64::INFINITY;
        }
    }
    (digits, stats)
}

#[test]
fn certified_weight_preparation_boundaries() {
    // Independent FP32/Euclidean reference, including domain endpoints, signed
    // zeros, invalid finite values, infinities/NaNs, and nontrivial quantization.
    let special = [
        0_u16,
        0x8000,
        1,
        0x8001,
        (77 << 7) - 1,
        77 << 7,
        (77 << 7) + 1,
        157 << 7,
        (157 << 7) + 1,
        0x7f80,
        0xff80,
        0x7fc1,
    ];
    let nr = special.len() + 16;
    let mut weights = vec![0_u16; nr * 4096];
    for (row, values) in weights.chunks_exact_mut(4096).enumerate() {
        for (k, value) in values.iter_mut().enumerate() {
            *value = if row < special.len() {
                if k == 2047 { special[row] } else { 0x3f80 }
            } else {
                // Vary mantissas, signs and 80 exponents within the guarded domain.
                (((77 + (k * 17 + row * 11) % 80) as u16) << 7)
                    | (((k * 37 + row) % 128) as u16)
                    | (((k + row) % 2) as u16) << 15
            };
        }
    }
    let values: Vec<f32> = weights
        .iter()
        .map(|&v| f32::from_bits((v as u32) << 16))
        .collect();
    let expected = certificate_host_rows(&values, nr);
    let actual = crate::gpu::certified_head::prepare_weights(&weights);
    assert_eq!(actual.0, expected.0);
    assert_eq!(
        actual.1.iter().map(|v| v.to_bits()).collect::<Vec<_>>(),
        expected.1.iter().map(|v| v.to_bits()).collect::<Vec<_>>()
    );
    println!(
        "CERTIFIED_WEIGHT_PREPARATION {{\"rows\":{},\"values\":{}}}",
        nr,
        weights.len()
    );
}

fn certificate_reference(x: &[f32], selected: &[u32], weights: &[u16], nc: usize) -> Vec<f32> {
    selected
        .iter()
        .flat_map(|&r| {
            (0..nc).map(move |c| {
                let mut lanes = [0.0_f32; 32];
                for lane in 0..32 {
                    for k in (lane..4096).step_by(32) {
                        let product = x[r as usize * 4096 + k]
                            * f32::from_bits((weights[c * 4096 + k] as u32) << 16);
                        lanes[lane] += product;
                    }
                }
                for distance in [16, 8, 4, 2, 1] {
                    let old = lanes;
                    for lane in 0..32 - distance {
                        lanes[lane] = old[lane] + old[lane + distance];
                    }
                }
                let bits = lanes[0].to_bits();
                f32::from_bits(bits.wrapping_add(0x7fff + ((bits >> 16) & 1)) & 0xffff0000)
            })
        })
        .collect()
}

#[test]
fn certified_head_independent_reference() -> anyhow::Result<()> {
    use crate::graph::Graph;
    let context = CudaContext::new(0)?;
    let stream = context.new_stream()?;
    let module = device::load(&context)?;
    for (nr, nc) in [(1_usize, 1_usize), (3, 16), (16, 65), (32, 65), (33, 16)] {
        let values: Vec<f32> = (0..nr * 4096)
            .map(|i| match i / 4096 {
                0 => 1.0,
                1 => {
                    if i % 4096 == 0 {
                        0.1234567
                    } else {
                        0.5
                    }
                }
                2 => 0.0,
                3 => 2.0_f32.powi(-60),
                4 => 2.0_f32.powi(40),
                _ => f32::from_bits(
                    (((110 + (i * 17 + i / 4096 * 7) % 25) as u32) << 23)
                        | ((((i * 37 + i / 4096 * 3) % 128) as u32) << 16)
                        | (((i % 2) as u32) << 31),
                ),
            })
            .collect();
        let selected: Vec<u32> = (0..nr).rev().map(|v| v as u32).collect();
        let weights: Vec<u16> = (0..nc * 4096)
            .map(|i| {
                let v = match i / 4096 {
                    0 => 0.25,
                    1 => 2.0_f32.powi(-60),
                    2 => 2.0_f32.powi(40),
                    _ => f32::from_bits(
                        (((100 + (i * 19 + i / 4096 * 11) % 50) as u32) << 23)
                            | ((((i * 13 + i / 4096 * 5) % 128) as u32) << 16)
                            | (((i % 3 == 0) as u32) << 31),
                    ),
                };
                (v.to_bits() >> 16) as u16
            })
            .collect();
        let wf: Vec<f32> = weights
            .iter()
            .map(|&w| f32::from_bits((w as u32) << 16))
            .collect();
        let (wq, ws) = certificate_host_rows(&wf, nc);
        let ordered: Vec<f32> = selected
            .iter()
            .flat_map(|&r| {
                values[r as usize * 4096..(r as usize + 1) * 4096]
                    .iter()
                    .copied()
            })
            .collect();
        let (expected_q, expected_stats) = certificate_host_rows(&ordered, nr);
        let reconstruct = |data: &[i8], rows: usize, row: usize, k: usize| -> i64 {
            data[row * 4096 + k] as i64
                + ((data[rows * 4096 + row * 4096 + k] as i64) << 8)
                + ((data[2 * rows * 4096 + row * 4096 + k] as i64) << 16)
        };
        let expected_center: Vec<i64> = (0..nr * nc)
            .map(|i| {
                (0..4096)
                    .map(|k| {
                        reconstruct(&expected_q, nr, i / nc, k) * reconstruct(&wq, nc, i % nc, k)
                    })
                    .sum()
            })
            .collect();
        let expected = certificate_reference(&values, &selected, &weights, nc);
        let packed = crate::packing::PackedBf16::new(&weights);
        let x = DeviceBuffer::from_host(&stream, &values)?;
        let selections = DeviceBuffer::from_host(&stream, &selected)?;
        let wq = DeviceBuffer::from_host(&stream, &wq)?;
        let words = DeviceBuffer::from_host(&stream, &packed.words)?;
        let offsets = DeviceBuffer::from_host(&stream, &packed.offsets)?;
        let exceptions = DeviceBuffer::from_host(&stream, &packed.exceptions)?;
        let mut xq = DeviceBuffer::<i8>::zeroed(&stream, 3 * nr * 4096)?;
        let mut xs = DeviceBuffer::<f64>::zeroed(&stream, nr * 5)?;
        let mut center = DeviceBuffer::<i64>::zeroed(&stream, nr * nc)?;
        let mut masks = DeviceBuffer::<u32>::zeroed(&stream, nc * nr.div_ceil(32))?;
        for forced in [false, true] {
            let mut current_stats = ws.clone();
            if forced {
                for c in 0..nc {
                    current_stats[c * 5 + 4] = f64::INFINITY;
                }
            }
            let ws = DeviceBuffer::from_host(&stream, &current_stats)?;
            for tile in [32, 64] {
                for graph in [false, true] {
                    // Fresh sentinels prove both launch forms actually publish all outputs.
                    let sentinel = -12345.25_f32;
                    let mut out = DeviceBuffer::from_host(&stream, &vec![sentinel; nr * nc + 64])?;
                    let mut launch = || -> anyhow::Result<()> {
                        unsafe {
                            module.head_certificate_inputs(
                                &stream,
                                rows(nr, 256),
                                &x,
                                &selections,
                                &mut xq,
                                &mut xs,
                            )?;
                            if tile == 32 {
                                module.head_integer_nine_products32(
                                    &stream,
                                    rows(nr.div_ceil(32) * nc.div_ceil(32), 128),
                                    &xq,
                                    &wq,
                                    nr as u32,
                                    nc as u32,
                                    4096,
                                    &mut center,
                                )?;
                            } else if tile == 64 {
                                module.head_integer_nine_products64(
                                    &stream,
                                    rows(nr.div_ceil(32) * nc.div_ceil(64), 256),
                                    &xq,
                                    &wq,
                                    nr as u32,
                                    nc as u32,
                                    4096,
                                    &mut center,
                                )?;
                            }
                            module.head_certify(
                                &stream,
                                rows((nc * nr.div_ceil(32)).div_ceil(8), 256),
                                &center,
                                &xs,
                                &ws,
                                nr as u32,
                                nc as u32,
                                &mut masks,
                                &mut out,
                            )?;
                            module.head_certificate_fallback(
                                &stream,
                                rows(masks.len().div_ceil(8), 256),
                                &x,
                                &selections,
                                &words,
                                &offsets,
                                &exceptions,
                                &masks,
                                nc as u32,
                                &mut out,
                            )?;
                        }
                        Ok(())
                    };
                    if graph {
                        let capture = unsafe { Graph::capture(&stream, false, launch)? };
                        unsafe {
                            capture.launch()?;
                        }
                        stream.synchronize()?;
                    } else {
                        launch()?;
                    }
                    let actual = out.to_host_vec(&stream)?;
                    assert_eq!(
                        actual[..nr * nc]
                            .iter()
                            .map(|v| v.to_bits())
                            .collect::<Vec<_>>(),
                        expected.iter().map(|v| v.to_bits()).collect::<Vec<_>>()
                    );
                    assert!(
                        actual[nr * nc..]
                            .iter()
                            .all(|&v| v.to_bits() == sentinel.to_bits())
                    );
                    assert_eq!(xq.to_host_vec(&stream)?, expected_q);
                    assert_eq!(center.to_host_vec(&stream)?, expected_center);
                    let actual_stats = xs.to_host_vec(&stream)?;
                    for row in 0..nr {
                        assert_eq!(actual_stats[row * 5], expected_stats[row * 5]);
                        assert_eq!(
                            actual_stats[row * 5 + 4].is_finite(),
                            expected_stats[row * 5 + 4].is_finite()
                        );
                    }
                    let masks_host = masks.to_host_vec(&stream)?;
                    let fallback: usize = masks_host.iter().map(|v| v.count_ones() as usize).sum();
                    for row in 0..nr {
                        for col in 0..nc {
                            let bit =
                                (masks_host[col * nr.div_ceil(32) + row / 32] >> (row % 32)) & 1;
                            if forced
                                || !expected_stats[row * 5 + 4].is_finite()
                                || !current_stats[col * 5 + 4].is_finite()
                            {
                                assert_eq!(bit, 1);
                            }
                        }
                    }
                    if forced {
                        assert_eq!(fallback, nr * nc);
                    } else {
                        assert!(fallback < nr * nc, "require some certified outputs");
                    }
                    println!(
                        "CERTIFIED_HEAD_CHECK {}",
                        serde_json::json!({"rows":nr,"columns":nc,"graph":graph,"forced":forced,"tile":tile,"fallback":fallback,"outputs":nr*nc})
                    );
                }
            }
        }
    }
    Ok(())
}

#[test]
#[ignore = "complete certified-head operator comparison on captured inputs; no model dispatch"]
fn certified_head_captured_profile() -> anyhow::Result<()> {
    use crate::{graph::Graph, model::Model};
    let root = PathBuf::from(std::env::var("CLEAN_MODEL_BUNDLE")?);
    let model = Model::load(&root)?;
    let captures = PathBuf::from(std::env::var("CLEAN_HEAD_CAPTURE_ROOT")?);
    let mut samples = Vec::new();
    let mut identities = Vec::new();
    for prompt in [5, 513] {
        for step in 0..3 {
            let path = captures.join(format!("k0-p{prompt}/step.{step}.norm.bin"));
            let bytes = fs::read(&path)?;
            assert!(bytes.len() >= 4096 * 4 && bytes.len() % (4096 * 4) == 0);
            identities.push(serde_json::json!({"path":path,"sha256":sha(&bytes)}));
            samples.push(
                bytes[bytes.len() - 4096 * 4..]
                    .chunks_exact(4)
                    .map(|b| f32::from_le_bytes(b.try_into().unwrap()))
                    .collect::<Vec<_>>(),
            );
        }
    }
    let nr = 32_usize;
    let nc = 151936_usize;
    let values: Vec<f32> = (0..nr)
        .flat_map(|i| samples[i % 6].iter().copied())
        .collect();
    let selected: Vec<u32> = (0..nr).map(|i| i as u32).collect();
    let wf: Vec<f32> = model
        .head
        .iter()
        .map(|&w| f32::from_bits((w as u32) << 16))
        .collect();
    let (wq, ws) = certificate_host_rows(&wf, nc);
    drop(wf);
    let context = CudaContext::new(0)?;
    let stream = context.new_stream()?;
    let module = device::load(&context)?;
    let packed = crate::packing::PackedBf16::new(&model.head);
    let packed_words = DeviceBuffer::from_host(&stream, &packed.words)?;
    let packed_offsets = DeviceBuffer::from_host(&stream, &packed.offsets)?;
    let packed_exceptions = DeviceBuffer::from_host(&stream, &packed.exceptions)?;
    drop(packed);
    let x = DeviceBuffer::from_host(&stream, &values)?;
    let selections = DeviceBuffer::from_host(&stream, &selected)?;
    let wq = DeviceBuffer::from_host(&stream, &wq)?;
    let ws = DeviceBuffer::from_host(&stream, &ws)?;
    let mut xq = DeviceBuffer::<i8>::zeroed(&stream, 3 * nr * 4096)?;
    let mut xs = DeviceBuffer::<f64>::zeroed(&stream, nr * 5)?;
    let mut center = DeviceBuffer::<i64>::zeroed(&stream, nr * nc)?;
    let mut masks = DeviceBuffer::<u32>::zeroed(&stream, nc)?;
    let mut out = DeviceBuffer::<f32>::zeroed(&stream, nr * nc)?;
    unsafe {
        module.head_packed_thirtytwo_staged(
            &stream,
            rows(nc / 8, 256),
            &x,
            &selections,
            &packed_words,
            &packed_offsets,
            &packed_exceptions,
            &mut out,
        )?;
    }
    let expected = out.to_host_vec(&stream)?;
    let start = context.new_event(Some(0))?;
    let end = context.new_event(Some(0))?;
    for stage in [
        "complete-32",
        "complete-64",
        "baseline",
        "inputs",
        "center-32",
        "center-64",
        "certify",
        "fallback",
    ] {
        if stage.starts_with("complete-") {
            out.copy_from_host(&stream, &vec![f32::NAN; nr * nc])?;
        }
        let graph = unsafe {
            Graph::capture(&stream, false, || {
                if stage.starts_with("complete-") || stage == "inputs" {
                    module.head_certificate_inputs(
                        &stream,
                        rows(nr, 256),
                        &x,
                        &selections,
                        &mut xq,
                        &mut xs,
                    )?;
                }
                if stage.starts_with("complete-") || stage.starts_with("center-") {
                    if stage.ends_with("-32") {
                        module.head_integer_nine_products32(
                            &stream,
                            rows(nc.div_ceil(32), 128),
                            &xq,
                            &wq,
                            nr as u32,
                            nc as u32,
                            4096,
                            &mut center,
                        )?;
                    } else {
                        module.head_integer_nine_products64(
                            &stream,
                            rows(nc.div_ceil(64), 256),
                            &xq,
                            &wq,
                            nr as u32,
                            nc as u32,
                            4096,
                            &mut center,
                        )?;
                    }
                }
                if stage.starts_with("complete-") || stage == "certify" {
                    module.head_certify(
                        &stream,
                        rows(nc / 8, 256),
                        &center,
                        &xs,
                        &ws,
                        nr as u32,
                        nc as u32,
                        &mut masks,
                        &mut out,
                    )?;
                }
                if stage.starts_with("complete-") || stage == "fallback" {
                    module.head_certificate_fallback(
                        &stream,
                        rows(nc / 8, 256),
                        &x,
                        &selections,
                        &packed_words,
                        &packed_offsets,
                        &packed_exceptions,
                        &masks,
                        nc as u32,
                        &mut out,
                    )?;
                }
                if stage == "baseline" {
                    module.head_packed_thirtytwo_staged(
                        &stream,
                        rows(nc / 8, 256),
                        &x,
                        &selections,
                        &packed_words,
                        &packed_offsets,
                        &packed_exceptions,
                        &mut out,
                    )?;
                }
                Ok(())
            })?
        };
        let mut times = Vec::new();
        for iteration in 0..10 {
            let _eviction = DeviceBuffer::<u8>::zeroed(&stream, 256 << 20)?;
            start.record(&stream)?;
            unsafe {
                graph.launch()?;
            }
            end.record(&stream)?;
            let ms = start.elapsed_ms(&end)?;
            if iteration >= 3 {
                times.push(ms);
            }
        }
        let actual = out.to_host_vec(&stream)?;
        assert_eq!(
            actual.iter().map(|v| v.to_bits()).collect::<Vec<_>>(),
            expected.iter().map(|v| v.to_bits()).collect::<Vec<_>>()
        );
        let fallback: u64 = masks
            .to_host_vec(&stream)?
            .iter()
            .map(|v| v.count_ones() as u64)
            .sum();
        assert!(fallback > 0 && fallback < (nr * nc) as u64);
        println!(
            "CERTIFIED_HEAD_PROFILE {}",
            serde_json::json!({"rows":nr,"columns":nc,"stage":stage,"milliseconds":times,"fallback":fallback,"outputs":nr*nc,"model_root":model.root,"input_identities":identities,"device":context.device_name()?,"scope":"Unpaired operator screen on six captured input rows repeated to batch 32; complete includes dynamic input preparation, center, certification and exact fallback; phase timings are separate diagnostics."})
        );
    }
    Ok(())
}

#[test]
fn square_projection_reference() -> anyhow::Result<()> {
    let context = CudaContext::new(0)?;
    let stream = context.new_stream()?;
    let module = device::load(&context)?;
    let mut cases: Vec<_> = [
        1_usize, 3, 15, 16, 17, 31, 32, 33, 63, 64, 65, 127, 128, 129, 255, 256, 257,
    ]
    .into_iter()
    .map(|nr| {
        (
            nr,
            if nr % 2 == 0 { 257 } else { 129 },
            if nr <= 32 { 128 } else { 384 },
            "mixed",
        )
    })
    .collect();
    cases.extend([
        (1, 129, 12288, "maximum"),
        (17, 129, 12288, "minimum"),
        (5, 1024, 4096, "mixed"),
    ]);
    for (nr, n, k, pattern) in cases {
        let input: Vec<i8> = (0..nr * k)
            .map(|i| match pattern {
                "maximum" => 127,
                "minimum" => -128,
                _ => {
                    (((i as u32).wrapping_mul(1664525).wrapping_add(1013904223) >> 16) as u8) as i8
                }
            })
            .collect();
        let weight: Vec<i8> = (0..n * k)
            .map(|i| {
                if pattern == "mixed" {
                    (((i as u32).wrapping_mul(22695477).wrapping_add(91) >> 13) as u8) as i8
                } else {
                    127
                }
            })
            .collect();
        let asc: Vec<f32> = (0..nr).map(|r| 0.00013 * (r % 7 + 1) as f32).collect();
        let ws: Vec<f32> = (0..n).map(|c| 0.00017 * (c % 13 + 1) as f32).collect();
        let sentinel = -12345.25_f32;
        let mut expected = vec![sentinel.to_bits(); nr * n + 64];
        // Independent signed 64-bit host dot products, then the declared two
        // FP32 scales and finite BF16 round-to-nearest/ties-to-even conversion.
        // Even the maximum supported dot magnitude is below signed i32 range.
        for r in 0..nr {
            for c in 0..n {
                let mut dot = 0_i64;
                for j in 0..k {
                    dot += input[r * k + j] as i64 * weight[c * k + j] as i64;
                }
                assert!(dot >= i32::MIN as i64 && dot <= i32::MAX as i64);
                let x = (dot as f32 * asc[r]) * ws[c];
                assert!(x.is_finite());
                let bits = x.to_bits();
                expected[r * n + c] = bits.wrapping_add(0x7fff + ((bits >> 16) & 1)) & 0xffff0000;
            }
        }
        let q = DeviceBuffer::from_host(&stream, &input)?;
        let w = DeviceBuffer::from_host(&stream, &weight)?;
        let a = DeviceBuffer::from_host(&stream, &asc)?;
        let b = DeviceBuffer::from_host(&stream, &ws)?;
        let mut output = DeviceBuffer::from_host(&stream, &vec![sentinel; nr * n + 64])?;
        for variant in 0..1 {
            for graph in [false, true] {
                output.copy_from_host(&stream, &vec![sentinel; nr * n + 64])?;
                // SAFETY: K is a positive multiple of 128, tail copies zero-fill
                // invalid rows/columns, and each of 128 threads owns its fragments.
                // Output guards preserve trailing sentinels; captured buffers outlive graphs.
                let mut launch = || -> anyhow::Result<()> {
                    unsafe {
                        module.linear_square_pipeline(
                            &stream,
                            rows(nr.div_ceil(32) * n.div_ceil(32), 128),
                            &q,
                            &a,
                            &w,
                            &b,
                            k as u32,
                            &mut output,
                        )?;
                        Ok(())
                    }
                };
                if graph {
                    let capture = unsafe { crate::graph::Graph::capture(&stream, false, launch)? };
                    unsafe {
                        capture.launch()?;
                    }
                    stream.synchronize()?;
                } else {
                    launch()?;
                }
                let actual: Vec<u32> = output
                    .to_host_vec(&stream)?
                    .iter()
                    .map(|v| v.to_bits())
                    .collect();
                assert_eq!(
                    actual, expected,
                    "square projection {nr}x{n}x{k}/{pattern}/variant={variant}/graph={graph}"
                );
                println!(
                    "SQUARE_PROJECTION_REFERENCE {}",
                    serde_json::json!({"rows":nr,"n":n,"k":k,"pattern":pattern,"variant":variant,"graph":graph})
                );
            }
        }
    }
    Ok(())
}

